5	/* White-box tests: pull in rbtree.c's internals (rb_node_t, rbtree_t,
6	 * RB_RED/RB_BLACK, rb_malloc) directly so hand-built, deliberately invalid
7	 * trees can be fed to rb_validate. The public API (include/rbtree.h) never
8	 * produces an invalid tree on its own -- rb_insert's fixup always leaves a
9	 * correct tree, and rb_delete isn't implemented yet -- so there is no way
10	 * to reach these cases through the frozen header alone. */
11	#include "../src/rbtree.c"
12	
13	static rb_node_t *make_node(const char *key, rb_color_t color) {
14	    rb_node_t *n = rb_malloc(sizeof(*n));
15	    assert(n != NULL);
16	    size_t klen = strlen(key) + 1;
17	    n->key = rb_malloc(klen);
18	    assert(n->key != NULL);
19	    memcpy(n->key, key, klen);
20	    n->value = NULL;
21	    n->color = color;
22	    n->parent = NULL;
23	    n->left = NULL;
24	    n->right = NULL;
25	    return n;
26	}
27	
28	static rbtree_t *make_tree(rb_node_t *root, size_t size) {
29	    rbtree_t *t = rb_create(NULL);
30	    assert(t != NULL);
31	    t->root = root;
32	    t->size = size;
33	    return t;
34	}
35	
36	static void test_validate_rejects_red_root(void) {
37	    rb_node_t *root = make_node("a", RB_RED);
38	    rbtree_t *t = make_tree(root, 1);
39	    assert(rb_validate(t) != 0);
40	    rb_destroy(t);
